<?php
function s41_concurrent($row,$modes){global $wpdb;$dir='/tmp/eipsi-s41-race-'.bin2hex(random_bytes(6));mkdir($dir,0700);file_put_contents($dir.'/input.json',wp_json_encode(array('row'=>$row,'modes'=>$modes,'config'=>s41_config())));chmod($dir.'/input.json',0600);$workers=array();$pipes=array();$key='eipsi-rct-'.md5($wpdb->prefix.':'.$row['config'].':'.$row['fp']);$locked=false;
try{m0_assert((int)$wpdb->get_var($wpdb->prepare('SELECT GET_LOCK(%s,5)',$key))===1,'Parent named lock');$locked=true;foreach($modes as$i=>$mode){$workers[$i]=proc_open(array(PHP_BINARY,__DIR__.'/concurrency-worker.php',$dir,(string)$i),array(0=>array('pipe','r'),1=>array('pipe','w'),2=>array('file',$dir.'/stderr'.$i,'a')),$pipes[$i]);m0_assert(is_resource($workers[$i]),'Worker');fclose($pipes[$i][0]);}$deadline=microtime(true)+20;foreach($modes as$i=>$mode)while(!file_exists($dir.'/ready'.$i)){m0_assert(microtime(true)<$deadline,'Ready barrier');usleep(10000);}touch($dir.'/start');foreach($modes as$i=>$mode)while(!file_exists($dir.'/attempt'.$i)){m0_assert(microtime(true)<$deadline,'Attempt barrier');usleep(10000);}usleep(100000);foreach($modes as$i=>$mode)m0_assert(!file_exists($dir.'/result'.$i),'Owner bypassed named lock');$wpdb->get_var($wpdb->prepare('SELECT RELEASE_LOCK(%s)',$key));$locked=false;foreach($modes as$i=>$mode)while(!file_exists($dir.'/result'.$i)){m0_assert(microtime(true)<$deadline,'Result barrier');usleep(10000);}$out=array();foreach($modes as$i=>$mode){$j=json_decode(file_get_contents($dir.'/result'.$i),true);m0_assert(!isset($j['error']),'Worker error');$out[]=$j['result'];}return$out;
}finally{if($locked)$wpdb->get_var($wpdb->prepare('SELECT RELEASE_LOCK(%s)',$key));foreach($workers as$i=>$w){if(proc_get_status($w)['running'])proc_terminate($w);fclose($pipes[$i][1]);proc_close($w);}foreach(glob($dir.'/*')as$f)unlink($f);rmdir($dir);}}
